 font-size: 12px;
 color: #999999;
 line-height: 1.5;
 letter-spacing: 0.02em;
 display: none;
 margin-bottom: 0.7rem;
}
.ig-source-text { letter-spacing: 0.02em; line-height: 1.5; }
.ig-logo-wrap {
 display: flex;
 align-items: center;
 flex-shrink: 0;
}
.ig-logo-wrap svg { margin-bottom: -7px; }
@media (max-width: 600px) {
 .ig { padding: 10px; }
 .ig-title { font-size: 20px; margin-bottom: 8px; }
 .ig-desc { font-size: 16px; }
 .ig-legend { font-size: 12px; gap: 3px 10px; margin-bottom: 10px; line-height: 1.3; }
 .ig-dot { width: 9px; height: 9px; }
 .ig-footer { font-size: 11px; margin-top: 10px; min-height: 0; }
 .ig-note { font-size: 11px; }
 .ig-logo-wrap svg { height: 28px; margin-bottom: -5px; }
