ack(v) { const y = C.categories[v]; return isMobile && v % 2 !== 0 ? null : y; // 手機版每兩年標一次 }, }, }, y: { min: 0, max: 50, border: { display: false }, grid: { color: '#FFFFFF', lineWidth: 1, drawTicks: false }, ticks: { stepSize: 10, font: { family: "'Inter', sans-serif", size: isMobile ? 12 : 13 }, color: '#999999', padding: isMobile ? 4 : 6, }, }, }, layout: { padding: { top: 16, right: 0, bottom: 0, left: 0 } }, barThickness: isMobile ? 14 : 28, }, }); })(); 出生、診斷與死亡，三者表面各自獨立，卻根植於相近的結構土壤，反映當代香港的生存圖景：一個把「不確定性」轉譯為可篩查風險、又把成功想像為必須及早規劃與持續監察的社會。在這樣的環境下，無論是教育制度還是學童成長都被「精神病化」——精神醫學的語言、診斷和治療都在「自上而下」的系統設計與「自下而上」的反饋中交織運作。 風險辨識，正是「教育-醫療-社福」系統設計的核心要義。然而，這意味著什麼？本文梳理精神健康的關鍵數據，剖析香港校園推行的自殺預防「三層應急機制」以及針對SEN學生的「三層支援模式」，檢視這套以守護「下一代」為名的制度如何運作，存在哪些落差，又可能帶來甚麼意料之外的後果。
